// ==UserScript==
// @name         PolyTrack Summer 1 TAS (frame-exact)
// @match        https://app-polytrack.kodub.com/*
// @run-at       document-start
// @grant        none
// ==/UserScript==
// Generated by tools/build_userscript.py from inputs/summer1.json - do not edit.
// Patches PolyTrack's physics worker so it applies the recorded inputs on exact
// 1 ms simulation frames. Load the track, then press W once to start; the TAS
// takes over (further real key presses are ignored by the car).
(() => {
  const SCHED = /*SCHED*/[];
  const ANCHOR = "for(;t.userControls.buffer.length>0&&t.userControls.buffer[0].frame<=t.frames;){";
  const RealWorker = window.Worker;
  window.Worker = function (url, opts) {
    const u = new URL(url, location.href);
    if (!/simulation_worker\.bundle\.js$/.test(u.pathname)) return new RealWorker(url, opts);
    const xhr = new XMLHttpRequest();
    xhr.open("GET", u.href, false);
    xhr.send();
    let src = xhr.responseText;
    if (!src.includes(ANCHOR)) {
      console.warn("[TAS] game version changed; worker patch anchor not found");
      return new RealWorker(url, opts);
    }
    const hook = `self.__tas=self.__tas||{i:0,s:${JSON.stringify(SCHED)}};` +
      `if(t.frames==0)self.__tas.i=0;{const T=self.__tas;t.userControls.buffer.length=0;` +
      `while(T.i<T.s.length&&T.s[T.i][0]<=t.frames){t.userControls[T.s[T.i][1]]=T.s[T.i][2];T.i++}}`;
    // The worker runs from a blob: URL, so resolve its relative loads against the game's base.
    const shim = `(()=>{const B=${JSON.stringify(u.href)},R=x=>typeof x==="string"?new URL(x,B).href:x;` +
      `const o=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(m,x,...a){return o.call(this,m,R(x),...a)};` +
      `const f=self.fetch;self.fetch=(x,...a)=>f(R(x),...a);` +
      `const i=self.importScripts;self.importScripts=(...x)=>i(...x.map(R))})();`;
    src = shim + src.replace(ANCHOR, hook + ANCHOR);
    console.log("[TAS] physics worker patched, " + SCHED.length + " events");
    return new RealWorker(URL.createObjectURL(new Blob([src], { type: "text/javascript" })), opts);
  };
})();
